$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$b='C:\Users\lolo\Downloads\MSM_TR2_Backups\TR2-001_20261101';$files=@();foreach($n in @('TR2-001_Flash_lecture1.bin','TR2-001_Flash_lecture2.bin')){$p=Join-Path $b $n;$f=Get-Item -LiteralPath $p;$h=Get-FileHash -Algorithm SHA256 -LiteralPath $p;$files+=[pscustomobject]@{Name=$n;Length=$f.Length;SHA256=$h.Hash}};[pscustomobject]@{Backups=$files;Disks=@(Get-Disk|Select Number,FriendlyName,SerialNumber,Size,PartitionStyle,BusType);Volumes=@(Get-Volume|Select DriveLetter,FileSystemLabel,FileSystem,Size,SizeRemaining,AllocationUnitSize)}|ConvertTo-Json -Depth 5